<span class="line"><span style="color:#E5C07B;">    Season</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Summer</span><span style="color:#ABB2BF;"> =&gt; </span><span style="color:#98C379;">&quot;夏&quot;</span><span style="color:#ABB2BF;">,</span></span>
